def is_samepatterns(colors, patterns):
    # Create a dictionary to map colors to patterns
    colors_dict = dict()
    # Iterate through the list of colors and patterns
    for color, pattern in zip(colors, patterns):
        # If the color is already in the dictionary, check if it matches the current pattern
        if color in colors_dict:
            if colors_dict[color] != pattern:
                return False
        else:
            # If the color is not in the dictionary, add it with the current pattern
            colors_dict[color] = pattern
    # If all colors match their corresponding patterns, return True
    return True
```

