def dict_depth(dic):
    # Check if the input is a dictionary
    if isinstance(dic, dict):
        # Recursively find the depth of each value if it's a dictionary
        return 1 + (max(map(dict_depth, dic.values())) if dic else 0)
    # Return 0 if the input is not a dictionary
    return 0
