def max_product(nums): 
    n = len(nums) 
    max_product_subseq = [0] * n 
    max_product_subseq[0] = nums[0] 

    for i in range(1, n): 
        max_product_subseq[i] = nums[i] 
        for j in range(i): 
            if nums[i] % nums[j] == 0 and max_product_subseq[i] < max_product_subseq[j] * nums[i]: 
                max_product_subseq[i] = max_product_subseq[j] * nums[i] 

    return max(max_product_subseq) 
```

