def find_first_occurrence(arr, x): 
    low = 0
    high = len(arr) - 1
    result = -1  # Initialize result to -1 to indicate if the number is not found
    while low <= high: 
        mid = (low + high) // 2
        if arr[mid] > x: 
            high = mid - 1
        elif arr[mid] < x: 
            low = mid + 1
        else: 
            result = mid  # Update result to current mid
            high = mid - 1  # Move left to find the first occurrence
    return result
